1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21		"time"
22	)
23	
24	// Version is the baseline release identifier.
25	const Version = "0.1.0"
26	
27	const metricsPath = "/api/v1/metrics"
28	
29	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
30	
31	type health struct {
32		Status  string `json:"status"`
33		Service string `json:"service"`
34		Version string `json:"version"`
35	}
36	
37	// series is one uniquely identified time series: name + full label set.
38	type series struct {
39		name   string
40		typ    string
41		labels map[string]string
42	
43		// counter/gauge state
44		value float64
45	
46		// histogram state
47		bucketBounds []float64 // strictly increasing, fixed at first write
48		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
49		count        int64
50		sum          float64
51	
52		// history holds accepted samples in commit order for range queries.
53		// Entries older than the retention window are ignored at query time;
54		// evicting them never touches the cumulative state above.
55		history []historyPoint
56	}
57	
58	type metricStore struct {
59		mu     sync.RWMutex
60		series map[string]*series
61	
62		// alert rules keyed by rule id; guarded by mu so rule replacement and
63		// alert evaluation are atomic with metric commits.
64		rules map[string]*alertRule
65	
66		// silences keyed by silence id; same lock so alert evaluation reads
67		// metrics, rules and silences from one consistent snapshot.
68		silences map[string]*silence
69	
70		// inhibit rules keyed by rule id; same lock so alert evaluation also
71		// reads inhibit rules from the same consistent snapshot.
72		inhibitions map[string]*inhibitRule
73	
74		// notification routes keyed by route id; same lock so the notification
75		// plan reads routes from the same snapshot as alert evaluation.
76		notificationRoutes map[string]*notificationRoute
77	
78		// SLO definitions keyed by SLO id; same lock so status evaluation reads
79		// definitions and counters from one consistent snapshot.
80		slos map[string]*sloDefinition
81	
82		// Log entries keyed by entry id; same lock so log commits and retrieval
83		// read one consistent snapshot. logOrder is the submission-order FIFO
84		// of ids used for eviction; logSeq is the commit sequence that anchors
85		// paginated read snapshots.
86		logs     map[string]*logEntry
87		logOrder []string
88		logSeq   int64
89	
90		// Spans keyed by tenant-unique "trace_id\x00span_id"; same lock so span
91		// commits and trace reads share the logs snapshot they join against.
92		// spanSeq is the commit sequence that anchors paginated trace searches.
93		spans   map[string]*span
94		spanSeq int64
95	
96		// Deterministic ingest sampling policy; same lock so a policy swap is
97		// atomic with respect to the log/span commits it governs.
98		sampling samplingPolicy
99	
100		// Discovery target snapshot; same lock so reloads swap one immutable
101		// snapshot pointer and queries always read a consistent generation.
102		discovery *discoverySnapshot
103	
104		// scrapeBaseline holds the last committed cumulative counter value per
105		// scraped series key; same lock so a target's batch and its baseline
106		// update commit atomically.
107		scrapeBaseline map[string]float64
108	}
109	
110	func newMetricStore() *metricStore {
111		return &metricStore{
112			series:             make(map[string]*series),
113			rules:              make(map[string]*alertRule),
114			silences:           make(map[string]*silence),
115			inhibitions:        make(map[string]*inhibitRule),
116			notificationRoutes: make(map[string]*notificationRoute),
117			slos:               make(map[string]*sloDefinition),
118			logs:               make(map[string]*logEntry),
119			spans:              make(map[string]*span),
120			sampling:           defaultSamplingPolicy(),
121			discovery:          emptyDiscoverySnapshot(),
122			scrapeBaseline:     make(map[string]float64),
123		}
124	}
125	
126	// validatedSample is a sample that passed all format and value checks.
127	type validatedSample struct {
128		key     string
129		name    string
130		typ     string
131		labels  map[string]string
132		value   float64
133		buckets []float64 // non-nil for histograms
134		ts      time.Time
135	}
136	
137	// checkAndApply validates the batch against the current state (and against
138	// itself) and then commits it in array order. A false result signals a type or
139	// bucket-boundary conflict; in that case no state is mutated.
140	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
141		s.mu.Lock()
142		defer s.mu.Unlock()
143	
144		// First pass: conflict detection against committed state and earlier
145		// samples in the same batch.
146		resolved := make(map[string]*series, len(batch))
147		for _, sm := range batch {
148			existing, ok := s.series[sm.key]
149			if !ok {
150				if shadow, seen := resolved[sm.key]; seen {
151					existing, ok = shadow, true
152				}
153			}
154			if ok {
155				if existing.typ != sm.typ {
156					return false
157				}
158				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
159					return false
160				}
161				resolved[sm.key] = existing
162				continue
163			}
164			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
165		}
166	
167		// Second pass: commit in order.
168		for _, sm := range batch {
169			cur, ok := s.series[sm.key]
170			if !ok {
171				cur = &series{
172					name:         sm.name,
173					typ:          sm.typ,
174					labels:       sm.labels,
175					bucketBounds: append([]float64(nil), sm.buckets...),
176				}
177				if sm.typ == "histogram" {
178					cur.bucketCounts = make([]int64, len(sm.buckets))
179				}
180				s.series[sm.key] = cur
181			}
182			switch sm.typ {
183			case "counter":
184				cur.value += sm.value
185			case "gauge":
186				cur.value = sm.value
187			case "histogram":
188				cur.count++
189				cur.sum += sm.value
190				for i, bound := range cur.bucketBounds {
191					if sm.value <= bound {
192						cur.bucketCounts[i]++
193					}
194				}
195			}
196			cur.history = append(cur.history, historyPoint{ts: sm.ts, value: sm.value})
197		}
198		return true
199	}
200	
201	type seriesOutput struct {
202		Name    string            `json:"name"`
203		Type    string            `json:"type"`
204		Labels  map[string]string `json:"labels"`
205		Value   *float64          `json:"value,omitempty"`
206		Count   *int64            `json:"count,omitempty"`
207		Sum     *float64          `json:"sum,omitempty"`
208		Buckets []bucketOutput    `json:"buckets,omitempty"`
209	}
210	
211	type bucketOutput struct {
212		LE    float64 `json:"le"`
213		Count int64   `json:"count"`
214	}
215	
216	// query returns matching series as ready-to-encode outputs. A series matches
217	// when its name equals name exactly and it contains every selector label.
218	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
219		s.mu.RLock()
220		defer s.mu.RUnlock()
221	
222		out := make([]seriesOutput, 0)
223		for _, cur := range s.series {
224			if cur.name != name {
225				continue
226			}
227			matched := true
228			for k, v := range selector {
229				got, ok := cur.labels[k]
230				if !ok || got != v {
231					matched = false
232					break
233				}
234			}
235			if !matched {
236				continue
237			}
238			out = append(out, currentSeriesOutput(cur))
239		}
240	
241		sort.Slice(out, func(i, j int) bool {
242			return compareLabels(out[i].Labels, out[j].Labels) < 0
243		})
244		return out
245	}
246	
247	// compareLabels imposes a normalized lexicographic order on full label sets:
248	// keys are sorted, then (key, value) pairs are compared element-wise, and a
249	// shorter pair list sorts first when it is a prefix of a longer one.
250	func compareLabels(a, b map[string]string) int {
251		ka := sortedKeys(a)
252		kb := sortedKeys(b)
253		n := len(ka)
254		if len(kb) < n {
255			n = len(kb)
256		}
257		for i := 0; i < n; i++ {
258			if ka[i] != kb[i] {
259				return strings.Compare(ka[i], kb[i])
260			}
261			if a[ka[i]] != b[kb[i]] {
262				return strings.Compare(a[ka[i]], b[kb[i]])
263			}
264		}
265		switch {
266		case len(ka) < len(kb):
267			return -1
268		case len(ka) > len(kb):
269			return 1
270		default:
271			return 0
272		}
273	}
274	
275	func sortedKeys(m map[string]string) []string {
276		keys := make([]string, 0, len(m))
277		for k := range m {
278			keys = append(keys, k)
279		}
280		sort.Strings(keys)
281		return keys
282	}
283	
284	func copyLabels(in map[string]string) map[string]string {
285		out := make(map[string]string, len(in))
286		for k, v := range in {
287			out[k] = v
288		}
289		return out
290	}
291	
292	// seriesKey builds a collision-free identity from name + unordered labels.
293	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
294	// so length-prefixed values remove any ambiguity from arbitrary label values.
295	func seriesKey(name string, labels map[string]string) string {
296		var b strings.Builder
297		b.WriteString(name)
298		for _, k := range sortedKeys(labels) {
299			b.WriteByte(0)
300			b.WriteString(k)
301			b.WriteByte(0)
302			v := labels[k]
303			b.WriteString(strconv.Itoa(len(v)))
304			b.WriteByte(0)
305			b.WriteString(v)
306		}
307		return b.String()
308	}
309	
310	func equalBuckets(a, b []float64) bool {
311		if len(a) != len(b) {
312			return false
313		}
314		for i := range a {
315			if a[i] != b[i] {
316				return false
317			}
318		}
319		return true
320	}
321	
322	// Handler returns the HTTP surface served by SignalWatch.
323	func Handler() http.Handler {
324		return newHandler(newTenantRegistry())
325	}
326	
327	func newHandler(registry *tenantRegistry) http.Handler {
328		mux := http.NewServeMux()
329	
330		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
331			if r.Method != http.MethodGet {
332				w.Header().Set("Allow", http.MethodGet)
333				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
334				return
335			}
336			w.Header().Set("Content-Type", "application/json; charset=utf-8")
337			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
338		})
339	
340		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
341			switch r.Method {
342			case http.MethodGet:
343				handleMetricsGet(w, r)
344			case http.MethodPost:
345				handleMetricsPost(w, r)
346			default:
347				w.Header().Set("Allow", "GET, POST")
348				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
349			}
350		})
351	
352		registerAlertHandlers(mux)
353		registerSilenceHandlers(mux)
354		registerInhibitHandlers(mux)
355		registerNotificationRouteHandlers(mux)
356		registerSLOHandlers(mux)
357		registerQueryHandler(mux)
358		registerMetricRangeHandler(mux)
359		registerQueryRangeHandler(mux)
360		registerLogHandlers(mux)
361		registerSpanHandlers(mux)
362		registerSamplingPolicyHandlers(mux)
363		registerDiscoveryTargetHandlers(mux)
364		registerDiagnosticExportHandler(mux)
365	
366		return withTenants(mux, registry)
367	}
368	
369	func handleMetricsPost(w http.ResponseWriter, r *http.Request) {
370		// All samples in the request share this single receive instant: it is the
371		// default timestamp and the anchor for the accepted timestamp window.
372		receivedAt := time.Now()
373		store := tenantStore(r)
374		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
375		if err != nil || mediaType != "application/json" {
376			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
377			return
378		}
379	
380		body, err := io.ReadAll(r.Body)
381		if err != nil {
382			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
383			return
384		}
385	
386		batch, code := decodeMetricsBatch(body, receivedAt)
387		if code != "" {
388			writeAPIError(w, code, http.StatusBadRequest)
389			return
390		}
391	
392		if !store.checkAndApply(batch) {
393			writeAPIError(w, "metric_conflict", http.StatusConflict)
394			return
395		}
396	
397		w.Header().Set("Content-Type", "application/json; charset=utf-8")
398		w.WriteHeader(http.StatusAccepted)
399		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
400	}
401	
402	type metricsEnvelope struct {
403		Samples *[]json.RawMessage `json:"samples"`
404	}
405	
406	type rawSample struct {
407		Name      *string            `json:"name"`
408		Type      *string            `json:"type"`
409		Labels    *map[string]string `json:"labels"`
410		Value     *float64           `json:"value"`
411		Buckets   *[]float64         `json:"buckets"`
412		Timestamp *string            `json:"timestamp"`
413	}
414	
415	// decodeMetricsBatch performs every format and value check, including the
416	// optional per-sample timestamp. It never returns a partially validated
417	// batch. The returned error code is empty on success.
418	func decodeMetricsBatch(body []byte, receivedAt time.Time) ([]validatedSample, string) {
419		var env metricsEnvelope
420		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
421			return nil, "invalid_metrics"
422		}
423	
424		batch := make([]validatedSample, 0, len(*env.Samples))
425		for _, raw := range *env.Samples {
426			var sm rawSample
427			if !strictDecode(raw, &sm) {
428				return nil, "invalid_metrics"
429			}
430			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
431				return nil, "invalid_metrics"
432			}
433			name, typ := *sm.Name, *sm.Type
434			if !identPattern.MatchString(name) {
435				return nil, "invalid_metrics"
436			}
437			if typ != "counter" && typ != "gauge" && typ != "histogram" {
438				return nil, "invalid_metrics"
439			}
440			labels := *sm.Labels
441			if labels == nil {
442				return nil, "invalid_metrics" // explicit null labels
443			}
444			for k := range labels {
445				if !identPattern.MatchString(k) {
446					return nil, "invalid_metrics"
447				}
448			}
449			value := *sm.Value
450			if math.IsNaN(value) || math.IsInf(value, 0) {
451				return nil, "invalid_metrics" // encoding/json already rejects NaN/Inf tokens
452			}
453			if typ == "counter" && value < 0 {
454				return nil, "invalid_metrics"
455			}
456	
457			var buckets []float64
458			if typ == "histogram" {
459				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
460					return nil, "invalid_metrics"
461				}
462				buckets = append([]float64(nil), (*sm.Buckets)...)
463			} else if sm.Buckets != nil {
464				return nil, "invalid_metrics" // buckets only valid on histograms
465			}
466	
467			// The timestamp is optional; every sample without one shares the
468			// request's receive instant.
469			ts := receivedAt
470			if sm.Timestamp != nil {
471				parsed, err := time.Parse(time.RFC3339Nano, *sm.Timestamp)
472				if err != nil {
473					return nil, "invalid_metrics"
474				}
475				ts = parsed
476			}
477			if ts.Before(receivedAt.Add(-metricRetention)) || ts.After(receivedAt.Add(maxFutureSkew)) {
478				return nil, "metric_timestamp_out_of_range"
479			}
480	
481			batch = append(batch, validatedSample{
482				key:     seriesKey(name, labels),
483				name:    name,
484				typ:     typ,
485				labels:  copyLabels(labels),
486				value:   value,
487				buckets: buckets,
488				ts:      ts,
489			})
490		}
491		return batch, ""
492	}
493	
494	func validBuckets(buckets []float64) bool {
495		if len(buckets) == 0 {
496			return false
497		}
498		prev := math.Inf(-1)
499		for _, b := range buckets {
500			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
501				return false
502			}
503			prev = b
504		}
505		return true
506	}
507	
508	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
509	// values and non-object payloads for struct targets.
510	func strictDecode(data []byte, target any) bool {
511		dec := json.NewDecoder(bytes.NewReader(data))
512		dec.DisallowUnknownFields()
513		if err := dec.Decode(target); err != nil {
514			return false
515		}
516		var extra json.RawMessage
517		if err := dec.Decode(&extra); err != io.EOF {
518			return false
519		}
520		return true
521	}
522	
523	func handleMetricsGet(w http.ResponseWriter, r *http.Request) {
524		store := tenantStore(r)
525		values, err := url.ParseQuery(r.URL.RawQuery)
526		if err != nil {
527			writeAPIError(w, "invalid_query", http.StatusBadRequest)
528			return
529		}
530	
531		names := values["name"]
532		if len(names) == 0 || !identPattern.MatchString(names[0]) {
533			writeAPIError(w, "invalid_query", http.StatusBadRequest)
534			return
535		}
536	
537		selector := make(map[string]string)
538		for key, vals := range values {
539			if !strings.HasPrefix(key, "label.") {
540				continue
541			}
542			labelKey := strings.TrimPrefix(key, "label.")
543			if !identPattern.MatchString(labelKey) {
544				writeAPIError(w, "invalid_query", http.StatusBadRequest)
545				return
546			}
547			for _, v := range vals[1:] {
548				if v != vals[0] {
549					writeAPIError(w, "invalid_query", http.StatusBadRequest)
550					return
551				}
552			}
553			selector[labelKey] = vals[0]
554		}
555	
556		seriesList := store.query(names[0], selector)
557		w.Header().Set("Content-Type", "application/json; charset=utf-8")
558		_ = json.NewEncoder(w).Encode(map[string]any{"series": seriesList})
559	}
560	
561	func writeAPIError(w http.ResponseWriter, code string, status int) {
562		w.Header().Set("Content-Type", "application/json; charset=utf-8")
563		w.WriteHeader(status)
564		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": code}})
565	}
566

