50	// ---- request decoding ------------------------------------------------------
51	
52	type rawSLO struct {
53		Objective *float64     `json:"objective"`
54		Good      *rawRuleSide `json:"good"`
55		Total     *rawRuleSide `json:"total"`
56		Comment   *string      `json:"comment"`
57	}
58	
59	// decodeSLO parses and fully validates an SLO body. It never returns a
60	// partially validated definition.
61	func decodeSLO(body []byte) (*sloDefinition, bool) {
62		var raw rawSLO
63		if !strictDecode(body, &raw) {
64			return nil, false
65		}
66		if raw.Objective == nil || raw.Good == nil || raw.Total == nil || raw.Comment == nil {
67			return nil, false
68		}
69		objective := *raw.Objective
70		if math.IsNaN(objective) || math.IsInf(objective, 0) || objective <= 0 || objective >= 1 {
71			return nil, false
72		}
73		good, ok := decodeRawSide(raw.Good)
74		if !ok {
75			return nil, false
76		}
77		total, ok := decodeRawSide(raw.Total)
78		if !ok {
79			return nil, false
80		}
81		return &sloDefinition{
82			objective: objective,
83			good:      good,
84			total:     total,
85			comment:   *raw.Comment,
86		}, true
87	}
88	
89	// ---- store operations ------------------------------------------------------
90	
91	func (s *metricStore) putSLO(d *sloDefinition) bool {
92		s.mu.Lock()
93		defer s.mu.Unlock()
94		_, existed := s.slos[d.id]
95		s.slos[d.id] = d
96		return !existed
97	}
98	
99	func (s *metricStore) getSLO(id string) (*sloDefinition, bool) {
100		s.mu.RLock()
101		defer s.mu.RUnlock()
102		d, ok := s.slos[id]
103		return d, ok
104	}
105	
106	func (s *metricStore) deleteSLO(id string) bool {
107		s.mu.Lock()
108		defer s.mu.Unlock()
109		if _, ok := s.slos[id]; !ok {
110			return false
111		}
112		delete(s.slos, id)
113		return true
114	}
115	
116	// snapshotSLOs returns all definitions sorted by id. Definition objects are
117	// immutable, so the pointers stay safe after the lock is released.
118	func (s *metricStore) snapshotSLOs() []*sloDefinition {
119		s.mu.RLock()
120		defer s.mu.RUnlock()
121		return s.snapshotSLOsLocked()
122	}
123	
124	func (s *metricStore) snapshotSLOsLocked() []*sloDefinition {
125		out := make([]*sloDefinition, 0, len(s.slos))
126		for _, d := range s.slos {
127			out = append(out, d)
128		}
129		sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
130		return out
131	}
132	
133	// counterSum sums current values of all matching counter series. ok is false
134	// when no counter series matches; gauges and histograms are ignored, so a
135	// selector matching only those counts as unavailable.
136	func (s *metricStore) counterSum(sel *ruleSelector) (sum float64, ok bool) {
137		for _, cur := range s.series {
138			if cur.typ != "counter" {
139				continue
140			}
141			if cur.name != sel.metric {
142				continue
143			}
144			matched := true
145			for k, v := range sel.labels {
146				got, exists := cur.labels[k]
147				if !exists || got != v {
148					matched = false
149					break
150				}
151			}
152			if !matched {
153				continue
154			}
155			sum += cur.value
156			ok = true
157		}
158		return sum, ok
159	}
160	
161	// ---- status evaluation -----------------------------------------------------
162	
163	type sloStatusOutput struct {
164		ID                        string   `json:"id"`
165		State                     string   `json:"state"`
166		GoodEvents                *float64 `json:"good_events"`
167		TotalEvents               *float64 `json:"total_events"`
168		Compliance                *float64 `json:"compliance"`
169		ErrorBudgetTotal          *float64 `json:"error_budget_total"`
170		ErrorBudgetRemaining      *float64 `json:"error_budget_remaining"`
171		ErrorBudgetRemainingRatio *float64 `json:"error_budget_remaining_ratio"`
172	}
173	
174	// evalSLOStatus computes every SLO definition against a single consistent
175	// snapshot of definitions and counter series; results are sorted by id.
176	//
177	// Each side sums the current values of matching counters only. A side with no
178	// matching counter, or a zero total, yields no_data. Non-finite aggregates or
179	// good exceeding total yield invalid_data. In both cases every numeric field
180	// is null. Otherwise compliance, budget totals and remaining amounts are
181	// derived from the event counts; remaining amounts may go negative.
182	func (s *metricStore) evalSLOStatus() []sloStatusOutput {
183		s.mu.RLock()
184		defer s.mu.RUnlock()
185		return s.evalSLOStatusLocked()
186	}
187	
188	// evalSLOStatusLocked is evalSLOStatus for callers already holding the store
189	// lock, so the diagnostic package's SLO section shares one snapshot.
190	func (s *metricStore) evalSLOStatusLocked() []sloStatusOutput {
191		defs := s.snapshotSLOsLocked()
192		out := make([]sloStatusOutput, 0, len(defs))
193		for _, d := range defs {
194			st := sloStatusOutput{ID: d.id}
195	
196			good, goodOK := s.counterSum(d.good)
197			total, totalOK := s.counterSum(d.total)
198			switch {
199			case !goodOK || !totalOK || total == 0:
200				st.State = "no_data"
201			case math.IsNaN(good) || math.IsInf(good, 0) ||
202				math.IsNaN(total) || math.IsInf(total, 0) || good > total:
203				st.State = "invalid_data"
204			default:
205				compliance := good / total
206				budgetTotal := total * (1 - d.objective)
207				remaining := budgetTotal - (total - good)
208				remainingRatio := remaining / budgetTotal
209	
210				st.State = "breached"
211				if compliance >= d.objective {
212					st.State = "met"
213				}
214				st.GoodEvents = &good
215				st.TotalEvents = &total
216				st.Compliance = &compliance
217				st.ErrorBudgetTotal = &budgetTotal
218				st.ErrorBudgetRemaining = &remaining
219				st.ErrorBudgetRemainingRatio = &remainingRatio
220			}
221			out = append(out, st)
222		}
223		return out
224	}
