1	package server
2	
3	import (
4		"io"
5		"math"
6		"mime"
7		"net/http"
8		"net/url"
9		"sort"
10		"strings"
11		"time"
12	)
13	
14	const (
15		rollingSLOsPath       = "/api/v1/rolling-slos"
16		rollingSLORecordsPath = rollingSLOsPath + "/records"
17		rollingSLOReportPath  = rollingSLOsPath + "/report"
18	)
19	
20	// rollingSLO is a request-based rolling SLO definition plus its append-only
21	// record log. Definition fields never change after registration and records
22	// are only appended, so a report already handed out can never be mutated by
23	// later writes.
24	type rollingSLO struct {
25		name      string
26		objective float64
27		window    time.Duration
28		records   []rollingSLORecord
29	}
30	
31	// rollingSLORecord is one committed batch observation: total requests and
32	// failed requests attributed to a single timezone-aware instant.
33	type rollingSLORecord struct {
34		ts     time.Time
35		total  int64
36		failed int64
37	}
38	
39	// ---- JSON wire shapes ------------------------------------------------------
40	
41	type rollingSLOJSON struct {
42		Name          string  `json:"name"`
43		Objective     float64 `json:"objective"`
44		WindowSeconds float64 `json:"window_seconds"`
45	}
46	
47	func rollingSLOWireJSON(d *rollingSLO) rollingSLOJSON {
48		return rollingSLOJSON{
49			Name:          d.name,
50			Objective:     d.objective,
51			WindowSeconds: float64(d.window) / float64(time.Second),
52		}
53	}
54	
55	// ---- request decoding ------------------------------------------------------
56	
57	type rawRollingSLO struct {
58		Name          *string  `json:"name"`
59		Objective     *float64 `json:"objective"`
60		WindowSeconds *float64 `json:"window_seconds"`
61	}
62	
63	// decodeRollingSLO parses and fully validates a definition body. It never
64	// returns a partially validated definition.
65	func decodeRollingSLO(body []byte) (name string, objective float64, window time.Duration, ok bool) {
66		var raw rawRollingSLO
67		if !strictDecode(body, &raw) {
68			return "", 0, 0, false
69		}
70		if raw.Name == nil || raw.Objective == nil || raw.WindowSeconds == nil {
71			return "", 0, 0, false
72		}
73		name = *raw.Name
74		if strings.TrimSpace(name) == "" {
75			return "", 0, 0, false
76		}
77		objective = *raw.Objective
78		if math.IsNaN(objective) || math.IsInf(objective, 0) || objective <= 0 || objective >= 1 {
79			return "", 0, 0, false
80		}
81		seconds := *raw.WindowSeconds
82		if math.IsNaN(seconds) || math.IsInf(seconds, 0) || seconds <= 0 ||
83			seconds >= float64(math.MaxInt64)/float64(time.Second) {
